// Robot Playground front end (10 Oct). Shared by the local page (play/static/index.html) and the site page
// (ayushdeshmukh/projects/robot-playground/index.html): both are generated by play/make_pages.py from play/page_body.html.
// The robot is a server on a GPU box; this page talks to it by websocket. Same origin when the page is served by the robot itself
// ("/" or "/site/..."), else ?server=host:port, else (on localhost) 127.0.0.1:8800, else the robot counts as offline.
const OBJ = ["cube", "cylinder"], MAX = 10;
const $ = id => document.getElementById(id);
const text = ([k, o, d]) => k === "pick-lift" ? `pick up the ${OBJ[o]}` :
  k === "push" ? `push the ${OBJ[o]} to the target` : `put the ${OBJ[o]} on ${d === 0 ? "the target" : "the " + OBJ[1 - o]}`;
let draft = [], ready = false, ws = null, url = null, mode = "build", last = null;

// ---------- sentence builder (the same rules as play/playground.py check_chain) ----------
function sim(chain) {
  const pos = {0: "table", 1: "table"}; let held = null;
  for (const [k, o, d] of chain) {
    if (k === "push") pos[o] = "target"; else if (k === "pick-lift") held = o; else { pos[o] = d === 0 ? "target" : "on"; held = null; }
  }
  return {pos, held};
}
function moves() {
  if (draft.length >= MAX) return [];
  const {pos, held} = sim(draft), out = [];
  const targetFree = !Object.values(pos).includes("target");
  if (draft.length === 0) for (const o of [0, 1]) out.push(["push", o, 0]);
  if (held === null) { for (const o of [0, 1]) if (pos[1 - o] !== "on") out.push(["pick-lift", o, 2]); }
  else {
    if (targetFree || pos[held] === "target") out.push(["place-down", held, 0]);
    out.push(["place-down", held, 1]);
  }
  return out;
}
function renderBuild() {
  $("moves").innerHTML = "";
  for (const m of moves()) {
    const b = document.createElement("button"); b.textContent = text(m);
    b.onclick = () => { draft.push(m); renderBuild(); }; $("moves").appendChild(b);
  }
  $("draft").innerHTML = draft.length ? draft.map(c => `<span class="cmd">${text(c)}</span>`).join(", then ") : '<span class="empty">Click commands above.</span>';
  $("run").disabled = !draft.length || !ready; $("run").textContent = ready ? "Run" : "Run (not connected)";
  $("undo").disabled = $("clear").disabled = !draft.length;
}

// ---------- tic-tac-toe ----------
function renderTtt(g) {
  const cells = $("board").children;
  for (let k = 0; k < 9; k++) {
    const v = g.board[k];
    cells[k].textContent = v === "X" ? "X" : v === "O" ? "O" : "";
    cells[k].disabled = !!v || g.turn !== "human" || !!g.result || !ready;
  }
  $("ttt-note").textContent = g.note || "";
  if (g.diff && $("ttt-diff").value !== g.diff && document.activeElement !== $("ttt-diff")) $("ttt-diff").value = g.diff;
}

// ---------- tower duel ----------
function renderTower(g) {
  const names = {4: "tile", 3: "disc"};
  $("stack").innerHTML = g.pieces.slice().reverse().map(p =>
    `<div class="piece ${names[p.type]} ${p.owner}"><span>${p.owner === "human" ? "you" : "robot"}: ${names[p.type]}</span></div>`).join("") || '<span class="empty">An empty table.</span>';
  $("tower-note").textContent = g.note || "";
  $("place").disabled = !(g.turn === "human" && !g.result && ready);
  $("dx").max = $("dy").max = g.max_offset_cm; $("dx").min = $("dy").min = -g.max_offset_cm;
  $("dxv").textContent = $("dx").value; $("dyv").textContent = $("dy").value;
}

// ---------- common ----------
function setMode(m, send) {
  mode = m;
  for (const id of ["build", "ttt", "tower"]) { $("panel-" + id).hidden = id !== m; $("tab-" + id).classList.toggle("on", id === m); }
  if (send && ws && ready) ws.send(JSON.stringify({type: "mode", mode: m, difficulty: $("ttt-diff").value}));
}
function onStatus(m) {
  last = m;
  $("left").textContent = m.left > 0 ? `${Math.floor(m.left / 60)}:${String(m.left % 60).padStart(2, "0")} left` : "";
  if (m.mode !== mode) setMode(m.mode, false);
  if (m.note) $("msg").textContent = m.note;
  $("state").textContent = !ready ? $("state").textContent : m.running ? "The robot is working" : m.mode === "build" ? (m.commands.length ? "Finished" : "Your turn") : "";
  if (m.commands.length) {
    $("live").innerHTML = m.commands.map((c, i) => `<span class="cmd ${i < m.marked ? "done" : ""} ${m.running && i === m.marked ? "cur" : ""}">${c}${i < m.marked ? " (done)" : ""}</span>`).join(", then ");
    $("marks").textContent = `${m.marked} / ${m.commands.length}`;
  } else if (!m.running) { $("live").innerHTML = '<span class="empty">The robot is idle.</span>'; $("marks").textContent = "–"; }
  $("simdone").textContent = m.mode === "build" && m.commands.length ? (m.reached ? "yes" : "not yet") : "–";
  $("flag").style.width = `${Math.max(0, Math.min(1, m.done_p)) * 100}%`;
  $("backend").textContent = m.backend === "teacher" ? "Test mode: the robot is the privileged RL teacher, not the camera-only student." : "";
  if (m.mode === "ttt" && m.game) renderTtt(m.game);
  if (m.mode === "tower" && m.game) renderTower(m.game);
  if (m.mode === "build") renderBuild();
}
function serverBase() {
  const q = new URLSearchParams(location.search).get("server");
  if (q) return q;
  if (location.pathname === "/" || location.pathname.startsWith("/site/")) return location.host;
  return ["localhost", "127.0.0.1"].includes(location.hostname) ? "127.0.0.1:8800" : null;
}
function connect() {
  const base = serverBase();
  if (!base) { $("state").textContent = "The robot is offline right now."; return; }
  const secure = location.protocol === "https:" && !/^(127\.0\.0\.1|localhost)/.test(base);
  ws = new WebSocket((secure ? "wss://" : "ws://") + base + "/ws");
  ws.onerror = () => { $("state").textContent = "The robot is offline right now (could not reach " + base + ")."; };
  ws.onmessage = ev => {
    if (typeof ev.data !== "string") { if (url) URL.revokeObjectURL(url); url = URL.createObjectURL(ev.data); $("view").src = url; return; }
    const m = JSON.parse(ev.data);
    if (m.type === "queue") $("state").textContent = `In the queue: ${m.position} ahead of you`;
    else if (m.type === "slot") { ready = true; $("state").textContent = "Your turn"; renderBuild(); }
    else if (m.type === "error") $("msg").textContent = m.message;
    else if (m.type === "expired") { ready = false; $("state").textContent = "Idle too long: reload this page to play again"; renderBuild(); }
    else if (m.type === "status") onStatus(m);
  };
  ws.onclose = () => { ready = false; if (!/idle too long/i.test($("state").textContent)) $("state").textContent = "Disconnected (the robot may be offline)"; renderBuild(); };
}
const send = o => { if (ws && ready) ws.send(JSON.stringify(o)); };
$("run").onclick = () => { $("msg").textContent = ""; send({type: "run", chain: draft}); };
$("undo").onclick = () => { draft.pop(); renderBuild(); };
$("clear").onclick = () => { draft = []; renderBuild(); };
$("scene").onclick = () => send({type: "new_scene"});
for (const id of ["build", "ttt", "tower"]) $("tab-" + id).onclick = () => { $("msg").textContent = ""; setMode(id, true); };
// 15 Oct: ?modes=build (the public page) shows only the listed modes; tic-tac-toe and the tower need a model trained for them
const MODES = (new URLSearchParams(location.search).get("modes") || "build,ttt,tower").split(",");
for (const id of ["build", "ttt", "tower"]) if (!MODES.includes(id)) $("tab-" + id).hidden = true;
for (let k = 0; k < 9; k++) {
  const b = document.createElement("button"); b.className = "sq"; b.onclick = () => { $("msg").textContent = ""; send({type: "move", square: k}); };
  $("board").appendChild(b);
}
$("ttt-new").onclick = () => send({type: "mode", mode: "ttt", difficulty: $("ttt-diff").value});
$("ttt-diff").onchange = () => send({type: "mode", mode: "ttt", difficulty: $("ttt-diff").value});
$("tower-new").onclick = () => send({type: "new_scene"});
for (const id of ["dx", "dy"]) $(id).oninput = () => { $("dxv").textContent = $("dx").value; $("dyv").textContent = $("dy").value; };
$("place").onclick = () => { $("msg").textContent = ""; send({type: "place", dx: +$("dx").value, dy: +$("dy").value}); };
setMode("build", false); renderBuild(); connect();
